# -*- coding: utf-8 -*-
"""Die letzte Woche vor der Belagerung und Tag 21 im Kalender (Duc 01.11.2026). Texte sind Entwuerfe, Duc geht sie noch durch.

Tag 15 Frist, Tag 19 Manoever auf der Karte, Tag 20 Alvas Flinte und Kriegsrat, Tag 21 bis 23 sechs Wellen mit Bestandsaufnahme und Flicken am Morgen, danach der Bericht.
Abende und Naechte: ereignisse_belagerung_nacht.py.
Wiki: docs/wiki/welt/belagerung.md, docs/wiki/welt/akt2_kalender.md. Karte: kern/taktik.py."""
from ereignisse_basis import *  # noqa: F401,F403
from ereignisse_gag1 import P1  # noqa: E402

